import java.io.*;
import java.net.*;
import java.net.http.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/** Dedicated Chromium profile controlled through CDP, never the user's browser session. */
final class BrowserBridge implements AutoCloseable,WebSocket.Listener {
    final NetworkPolicy policy;final ConcurrentMap<Integer,CompletableFuture<Map<String,Object>>> pending=new ConcurrentHashMap<>();final AtomicInteger sequence=new AtomicInteger();final StringBuilder text=new StringBuilder();Process process;HttpClient client;WebSocket socket;Path profile;volatile URI origin;
    BrowserBridge(NetworkPolicy policy){this.policy=policy;}
    static Path executable(){for(String path:List.of("C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe","C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe","C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe"))if(Files.isRegularFile(Path.of(path)))return Path.of(path);return null;}
    void start()throws Exception{if(socket!=null)return;Path exe=executable();if(exe==null)throw new IOException("Install Edge or Chrome to use Browser");profile=Files.createTempDirectory("vuln-browser-");process=new ProcessBuilder(exe.toString(),"--headless=new","--remote-debugging-address=127.0.0.1","--remote-debugging-port=0","--user-data-dir="+profile,"--no-first-run","--no-default-browser-check","about:blank").redirectOutput(ProcessBuilder.Redirect.DISCARD).redirectError(ProcessBuilder.Redirect.DISCARD).start();Path active=profile.resolve("DevToolsActivePort");long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(15);while(!Files.exists(active)&&System.nanoTime()<deadline){if(!process.isAlive())throw new IOException("Browser exited");Thread.sleep(100);}if(!Files.exists(active))throw new IOException("Browser debugging endpoint timed out");int port=Integer.parseInt(Files.readAllLines(active).getFirst());{client=HttpClient.newHttpClient();var response=client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/json/list")).build(),HttpResponse.BodyHandlers.ofString());List<?> pages=(List<?>)Json.parse(response.body());Map<String,Object> page=pages.stream().map(Json::object).filter(p->"page".equals(p.get("type"))).findFirst().orElseThrow();socket=client.newWebSocketBuilder().buildAsync(URI.create(page.get("webSocketDebuggerUrl").toString()),this).get(10,TimeUnit.SECONDS);}call("Page.enable",Map.of());call("Runtime.enable",Map.of());call("Fetch.enable",Map.of("patterns",List.of(Map.of("urlPattern","*"))));}
    CompletableFuture<Map<String,Object>> send(String method,Map<String,Object> params){int id=sequence.incrementAndGet();CompletableFuture<Map<String,Object>> future=new CompletableFuture<>();pending.put(id,future);socket.sendText(Json.write(Map.of("id",id,"method",method,"params",params)),true).exceptionally(ex->{pending.remove(id);future.completeExceptionally(ex);return null;});return future;}
    Map<String,Object> call(String method,Map<String,Object> params)throws Exception{return send(method,params).get(15,TimeUnit.SECONDS);}
    public void onOpen(WebSocket ws){ws.request(1);}
    public CompletionStage<?> onText(WebSocket ws,CharSequence chars,boolean last){if(text.length()+chars.length()>16*1024*1024){ws.abort();return null;}text.append(chars);if(last){String value=text.toString();text.setLength(0);try{Map<String,Object> message=Json.object(Json.parse(value));if(message.get("id") instanceof Number id){var future=pending.remove(id.intValue());if(future!=null){if(message.containsKey("error"))future.completeExceptionally(new IOException(Json.write(message.get("error"))));else future.complete(Json.object(message.getOrDefault("result",Map.of())));}}else if("Fetch.requestPaused".equals(message.get("method"))){var params=Json.object(message.get("params"));var request=Json.object(params.get("request"));URI uri=URI.create(request.get("url").toString());boolean allow=(uri.getScheme().equals("http")||uri.getScheme().equals("https"))&&origin!=null&&WorkbenchCore.sameOrigin(origin,uri)&&policy.allows(uri);send(allow?"Fetch.continueRequest":"Fetch.failRequest",allow?Map.of("requestId",params.get("requestId")):Map.of("requestId",params.get("requestId"),"errorReason","BlockedByClient"));}}catch(Exception ignored){}}ws.request(1);return null;}
    Map<String,Object> render(URI uri,boolean instrument)throws Exception{policy.requireScope(uri);start();origin=uri;if(policy.cookieJar){List<Object> cookies=new ArrayList<>();for(HttpCookie c:policy.cookies.getCookieStore().get(uri)){if(c.hasExpired())continue;cookies.add(Map.of("name",c.getName(),"value",c.getValue(),"url",NetworkPolicy.origin(uri),"secure",c.getSecure(),"httpOnly",c.isHttpOnly()));}if(!cookies.isEmpty())call("Network.setCookies",Map.of("cookies",cookies));}if(instrument)call("Page.addScriptToEvaluateOnNewDocument",Map.of("source","window.__vulnSinks=[];const d=Object.getOwnPropertyDescriptor(Element.prototype,'innerHTML');Object.defineProperty(Element.prototype,'innerHTML',{get:d.get,set:function(v){if(window.__vulnSinks.length<100)window.__vulnSinks.push({sink:'innerHTML',sample:String(v).slice(0,120)});return d.set.call(this,v);}});"));call("Page.navigate",Map.of("url",uri.toString()));long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(12);while(System.nanoTime()<deadline){Thread.sleep(150);var ready=call("Runtime.evaluate",Map.of("expression","document.readyState","returnByValue",true));if("complete".equals(Json.object(ready.get("result")).get("value")))break;}Thread.sleep(300);var result=call("Runtime.evaluate",Map.of("expression","({url:location.href,title:document.title,html:document.documentElement.outerHTML,links:Array.from(document.querySelectorAll('a[href]')).map(a=>a.href),forms:Array.from(document.forms).map(f=>({method:f.method,action:f.action})),scripts:Array.from(document.scripts).map(s=>s.src||'[inline]'),sinks:window.__vulnSinks||[]})","returnByValue",true));Map<String,Object> remote=Json.object(result.get("result"));return Json.object(remote.get("value"));}
    public void onError(WebSocket ws,Throwable error){pending.values().forEach(f->f.completeExceptionally(error));pending.clear();}
    public void close(){if(socket!=null)socket.abort();socket=null;if(client!=null)client.close();client=null;if(process!=null){process.descendants().forEach(ProcessHandle::destroy);process.destroy();try{if(!process.waitFor(3,TimeUnit.SECONDS))process.destroyForcibly();}catch(InterruptedException e){Thread.currentThread().interrupt();}}process=null;/* Dedicated profiles retained for diagnostic review; never touch user profiles. */}
}
